import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, T, words, DUR, Camara, Brillo, Profundidad, h, Easing, interpolate, clamp} from './kit';

// FE 2026-11-21 06:00 - oracion de la mujer que espera un resultado. VISUAL DE PAZ: camara que respira,
// fundidos de luz entre sitios, polvo de luz siempre flotando. Todo el tiempo sale de las palabras del guion.
const INI = words.map((w, i) => (w.f ? i : -1)).filter((i) => i >= 0);
const E3 = T(INI[2]);
const E4 = T(INI[3]);
const ABRAZAR = en('abrazar');
const RESPIRO = en('respiro');
const MIEDO1 = en('miedo', 1);
const PAPEL = en('papel');
const SALMO = en('Salmo');
const HOY = en('Hoy');
const SUELTO = en('Suelto');
const TEL = en('teléfono');
const BUSCO = en('busco');
const PAZ = en('paz');
const FAMILIA = en('familia');
const PECHO = en('pecho');
const ABRACE = en('abrace');
const MEDICOS = en('médicos');
const RESULT2 = en('resultado', 2);
const NOTICIA2 = en('noticia', 2);
const AGARRADA = en('agarrada');
const MANO2 = en('mano', 2);
const PERO = en('Pero');
const CONFIAMOS = en('confiamos');
const JESUS = en('Jesús');

const ease = Easing.inOut(Easing.cubic);
const sal = Easing.out(Easing.cubic);
const rampa = (s: number, a: number, b: number, v0 = 0, v1 = 1, e: (x: number) => number = ease) => interpolate(s, [a, Math.max(b, a + 0.001)], [v0, v1], {...clamp, easing: e});

type Piel = {b: string; l: string; o: string};
const PIEL_M: Piel = {b: '#a5683f', l: '#cf9163', o: '#6e4026'};
const PIEL_H: Piel = {b: '#8f5834', l: '#b97c52', o: '#5e3520'};
const PIEL_J: Piel = {b: '#9a6139', l: '#c58558', o: '#664024'};
const PIEL_D1: Piel = {b: '#e2ab82', l: '#f4cba8', o: '#b9805a'};
const PIEL_D2: Piel = {b: '#9a6340', l: '#bd8359', o: '#6c4128'};
const MOSTAZA: [string, string] = ['#e9b23e', '#a8741c'];
const GRIS: [string, string] = ['#a7adb4', '#5d646d'];
const VERDE: [string, string] = ['#4f8a78', '#27504a'];

// ---------- piezas de dibujo ----------
const Busto: React.FC<{id: string; x: number; y: number; sc?: number; piel: Piel; ropa: [string, string]; pelo: string; tipo: 'mujer' | 'hombre' | 'joven'; canas?: boolean; mir?: [number, number]; boca?: 'serena' | 'sonrisa' | 'triste'; inc?: number; resp?: number; largo?: number; op?: number}> = ({
  id, x, y, sc = 1, piel, ropa, pelo, tipo, canas, mir = [0, 2], boca = 'serena', inc = 0, resp = 0, largo = 330, op = 1,
}) => {
  const {s} = useS();
  const parp = (s + (x % 7) * 0.37) % 4.3 < 0.11 ? 0.12 : 1;
  const torso = `M-140 ${largo} L-132 30 Q-128 -32 -78 -48 Q-40 -60 -30 -76 L30 -76 Q40 -60 78 -48 Q128 -32 132 30 L140 ${largo} Z`;
  const mx = Math.max(-3.5, Math.min(3.5, mir[0]));
  const my = Math.max(-2.5, Math.min(2.5, mir[1]));
  const bocaD = boca === 'sonrisa' ? 'M-20 -150 Q0 -131 20 -150' : boca === 'triste' ? 'M-14 -143 Q0 -151 14 -143' : 'M-14 -148 Q0 -142 14 -148';
  return (
    <g transform={`translate(${x} ${y}) scale(${sc})`} opacity={op}>
      <defs>
        <linearGradient id={'r' + id} x1="0" x2="1" y1="0" y2="0"><stop offset="0" stopColor={ropa[0]} /><stop offset="1" stopColor={ropa[1]} /></linearGradient>
        <linearGradient id={'sh' + id} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#000" stopOpacity="0" /><stop offset="1" stopColor="#000" stopOpacity="0.4" /></linearGradient>
        <radialGradient id={'p' + id} cx="0.33" cy="0.3" r="0.85"><stop offset="0" stopColor={piel.l} /><stop offset="0.6" stopColor={piel.b} /><stop offset="1" stopColor={piel.o} /></radialGradient>
      </defs>
      {tipo === 'mujer' && (
        <g transform={`translate(0 ${-resp * 6})`}>
          <ellipse cx={0} cy={-190} rx={70} ry={82} fill={pelo} />
          <circle cx={0} cy={-276} r={37} fill={pelo} />
          <path d="M-26 -300 Q0 -316 26 -300" stroke="#fff" strokeOpacity={0.18} strokeWidth={6} fill="none" strokeLinecap="round" />
        </g>
      )}
      <g transform={`scale(1 ${1 + resp * 0.012}) translate(0 ${-resp * 5})`}>
        <path d={torso} fill={`url(#r${id})`} />
        <path d={torso} fill={`url(#sh${id})`} />
        <path d="M-32 -76 Q0 -46 32 -76" stroke="#000" strokeOpacity={0.3} strokeWidth={6} fill="none" strokeLinecap="round" />
      </g>
      <g transform={`translate(0 ${-resp * 6})`}>
        <path d="M-27 -122 L-27 -70 Q0 -46 27 -70 L27 -122Z" fill={`url(#p${id})`} />
        <path d="M-27 -104 Q0 -82 27 -104 L27 -122 L-27 -122Z" fill={piel.o} opacity={0.45} />
        <g transform={`rotate(${inc} 0 -70)`}>
          <circle cx={-61} cy={-182} r={15} fill={piel.b} />
          <circle cx={61} cy={-182} r={15} fill={piel.b} />
          <ellipse cx={0} cy={-190} rx={60} ry={72} fill={`url(#p${id})`} />
          {tipo === 'mujer' && <path d="M-62 -196 Q-68 -266 0 -270 Q68 -266 62 -196 Q52 -236 0 -240 Q-52 -236 -62 -196Z" fill={pelo} />}
          {tipo === 'mujer' && canas && (
            <g stroke="#e4e0dc" strokeWidth={4} fill="none" strokeLinecap="round" opacity={0.85}>
              <path d="M-56 -222 Q-44 -246 -18 -252" /><path d="M-48 -214 Q-36 -236 -12 -244" /><path d="M54 -224 Q42 -246 18 -252" />
            </g>
          )}
          {tipo !== 'mujer' && <path d="M-62 -200 Q-66 -266 0 -270 Q66 -266 62 -200 Q56 -238 0 -242 Q-56 -238 -62 -200Z" fill={pelo} />}
          {tipo !== 'mujer' && (
            <g fill={pelo}>
              <path d="M-36 -258 L-48 -290 L-16 -266Z" /><path d="M6 -266 L16 -298 L34 -262Z" /><path d="M36 -256 L58 -280 L56 -240Z" />
            </g>
          )}
          {[-24, 24].map((ex) => (
            <g key={ex} transform={`translate(${ex} -192) scale(1 ${parp})`}>
              <ellipse cx={0} cy={0} rx={12} ry={9} fill="#fffaf2" />
              <circle cx={mx} cy={my} r={6.6} fill="#1b120e" />
              <circle cx={mx + 2.4} cy={my - 2.6} r={2.3} fill="#fff" />
              <path d="M-12 -1 Q0 -12 12 -1" stroke={piel.o} strokeWidth={3} fill="none" strokeLinecap="round" />
            </g>
          ))}
          <path d="M-40 -212 Q-26 -220 -10 -224" stroke={pelo} strokeWidth={5} fill="none" strokeLinecap="round" />
          <path d="M40 -212 Q26 -220 10 -224" stroke={pelo} strokeWidth={5} fill="none" strokeLinecap="round" />
          <path d="M3 -190 Q11 -170 0 -165" stroke={piel.o} strokeOpacity={0.55} strokeWidth={4} fill="none" strokeLinecap="round" />
          <ellipse cx={-38} cy={-160} rx={14} ry={8} fill="#ff7a6a" opacity={0.16} />
          <ellipse cx={38} cy={-160} rx={14} ry={8} fill="#ff7a6a" opacity={0.16} />
          <path d={bocaD} stroke="#5a2a22" strokeWidth={5} fill="none" strokeLinecap="round" />
        </g>
      </g>
    </g>
  );
};

// Brazo 2D: hombro -> codo -> mano, con grosor que se afina, manga del color de la ropa y muneca de piel.
const seg = (p: [number, number], q: [number, number], w1: number, w2: number) => {
  const dx = q[0] - p[0];
  const dy = q[1] - p[1];
  const d = Math.hypot(dx, dy) || 1;
  const nx = -dy / d;
  const ny = dx / d;
  return `M${p[0] + (nx * w1) / 2} ${p[1] + (ny * w1) / 2} L${q[0] + (nx * w2) / 2} ${q[1] + (ny * w2) / 2} L${q[0] - (nx * w2) / 2} ${q[1] - (ny * w2) / 2} L${p[0] - (nx * w1) / 2} ${p[1] - (ny * w1) / 2}Z`;
};
const Brazo: React.FC<{a: [number, number]; b: [number, number]; e?: [number, number]; color: string; piel: Piel; w?: number; dir?: number}> = ({a, b, e, color, piel, w = 50, dir = 1}) => {
  let el: [number, number];
  if (e) el = e;
  else {
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const d = Math.hypot(dx, dy) || 1;
    const L = d * 0.5 + 8;
    const hh = Math.sqrt(Math.max(0, L * L - (d / 2) * (d / 2)));
    el = [(a[0] + b[0]) / 2 + (-dy / d) * hh * dir, (a[1] + b[1]) / 2 + (dx / d) * hh * dir];
  }
  const m: [number, number] = [el[0] + (b[0] - el[0]) * 0.8, el[1] + (b[1] - el[1]) * 0.8];
  const ang = (Math.atan2(b[1] - el[1], b[0] - el[0]) * 180) / Math.PI;
  const w2 = w * 0.84;
  const w3 = w * 0.6;
  const cx = (m[0] + b[0]) / 2;
  const cy = (m[1] + b[1]) / 2;
  return (
    <g>
      <path d={seg(m, b, w3 * 0.9, w3 * 0.72)} fill={piel.b} />
      <path d={seg(a, el, w, w2)} fill={color} />
      <circle cx={a[0]} cy={a[1]} r={w / 2} fill={color} />
      <circle cx={el[0]} cy={el[1]} r={w2 / 2} fill={color} />
      <path d={seg(el, m, w2, w3)} fill={color} />
      <path d={seg(a, el, w * 0.3, w2 * 0.26)} fill="#000" opacity={0.13} transform={`translate(${w * 0.2} 0)`} />
      <path d={seg(el, m, w2 * 0.3, w3 * 0.3)} fill="#000" opacity={0.13} transform={`translate(${w * 0.16} 0)`} />
      <path d={seg(a, el, w * 0.18, w2 * 0.16)} fill="#fff" opacity={0.14} transform={`translate(${-w * 0.2} 0)`} />

      <g transform={`translate(${m[0]} ${m[1]}) rotate(${ang})`}><rect x={-3} y={-w3 / 2 - 1} width={7} height={w3 + 2} rx={3} fill="#000" opacity={0.22} /></g>
      <g transform={`translate(${cx} ${cy}) rotate(${ang})`}>
        <ellipse cx={w * 0.3} cy={0} rx={w * 0.4} ry={w * 0.3} fill={piel.b} />
        <ellipse cx={w * 0.26} cy={-w * 0.08} rx={w * 0.24} ry={w * 0.14} fill={piel.l} opacity={0.7} />
        <ellipse cx={w * 0.5} cy={w * 0.1} rx={w * 0.16} ry={w * 0.12} fill={piel.b} />
        <ellipse cx={w * 0.26} cy={w * 0.25} rx={w * 0.2} ry={w * 0.08} fill={piel.o} opacity={0.4} />
      </g>
    </g>
  );
};
// Polvo de luz: motas que suben flotando entre y0 (abajo) y y1 (arriba).
const Polvo: React.FC<{n?: number; x0?: number; x1?: number; y0?: number; y1?: number; vel?: number; color?: string; sem?: number; op?: number; t0?: number; t1?: number}> = ({
  n = 24, x0 = 0, x1 = 1080, y0 = 1920, y1 = 0, vel = 26, color = 'rgba(255,236,190,1)', sem = 1, op = 0.8, t0 = 0, t1 = 9999,
}) => {
  const {s} = useS();
  const vis = rampa(s, t0, t0 + 0.8) * rampa(s, t1, t1 + 0.8, 1, 0);
  if (vis <= 0.001) return null;
  const rango = Math.max(50, y0 - y1);
  return (
    <AbsoluteFill style={{pointerEvents: 'none'}}>
      {Array.from({length: n}).map((_, i) => {
        const ciclo = (s * vel * (0.6 + h(i * 3 + sem) * 0.8) + h(i * 7 + sem) * rango) % rango;
        const y = y0 - ciclo;
        const x = x0 + h(i + sem * 5) * (x1 - x0) + Math.sin(s * 0.6 + i * 1.7) * 22;
        const r = 3 + h(i * 11 + sem) * 7;
        const a = Math.sin((ciclo / rango) * Math.PI) * op * vis;
        return <div key={i} style={{position: 'absolute', left: x - r, top: y - r, width: r * 2, height: r * 2, borderRadius: r * 2, background: `radial-gradient(circle, ${color} 0%, rgba(255,236,190,0) 70%)`, opacity: a}} />;
      })}
    </AbsoluteFill>
  );
};

// La camara respira: acercamiento y deslizamiento lentisimos y continuos.
const Respira: React.FC<{children: React.ReactNode}> = ({children}) => {
  const {s} = useS();
  const z = 1.03 + 0.016 * Math.sin(s * 0.8);
  return <AbsoluteFill style={{transform: `translate(${Math.sin(s * 0.31) * 14}px, ${Math.cos(s * 0.27) * 10}px) scale(${z})`, transformOrigin: '50% 50%'}}>{children}</AbsoluteFill>;
};

const Capa: React.FC<{op: number; children: React.ReactNode}> = ({op, children}) => <AbsoluteFill style={{opacity: op}}>{children}</AbsoluteFill>;

// ---------- COCINA (escenas 1, 2 y 4) ----------
const Cocina: React.FC<{fase: 1 | 4; paradas: {t: number; x: number; y: number; zoom: number}[]}> = ({fase, paradas}) => {
  const {s, lin} = useS();
  const f1 = fase === 1;
  // luz de la ventana: sube en 'busco' y al final
  const luz = f1 ? lin(BUSCO - 0.2, BUSCO + 1.6, 0.6, 1) : lin(E4, DUR, 0.8, 1);
  const respira = Math.sin(s * 1.5) * 0.6 + (f1 ? Math.max(0, 1 - Math.abs(s - RESPIRO - 0.3) * 1.2) * 0.7 : 0);
  // abrazo (fase 1): entran en 'abrazar', se sueltan y salen antes de 'papel'
  const kH = f1 ? Math.max(0, rampa(s, ABRAZAR - 0.35, ABRAZAR + 0.75, 0, 1, sal) - rampa(s, 8.4, 9.7)) : 0;
  const xMar = f1 ? 1260 + (800 - 1260) * kH : 1260 + (900 - 1260) * rampa(s, AGARRADA - 0.2, AGARRADA + 0.9, 0, 1, sal);
  const xHijo = -220 + (480 + 220) * kH;
  // mano izquierda (de ella): taza -> telefono -> taza
  const pT = f1 ? Math.min(rampa(s, TEL + 0.05, TEL + 0.55), rampa(s, BUSCO + 0.7, BUSCO + 1.3, 1, 0)) : 0;
  const hAx = 478 + (362 - 478) * pT;
  const hAy = 1230 + (1268 - 1230) * pT - Math.sin(pT * Math.PI) * 14;
  // mano derecha: descansa; en 'mano' (fase 4) busca la de su esposo
  const pM = f1 ? 0 : rampa(s, MANO2 - 0.35, MANO2 + 0.25, 0, 1, sal);
  const hBx = 772 + (824 - 772) * pM + Math.sin(s * 1.1) * 1.5;
  const hBy = 1262 - 14 * pM;
  const mirE = f1 ? (s > PAPEL - 0.5 && s < SALMO + 1.5 ? [3.5, 2] : s > TEL && s < BUSCO + 0.8 ? [-3.5, 2.5] : [-1.2, 3]) : s > AGARRADA && s < MANO2 + 1.5 ? [3.5, 2] : [0, 2];
  const bocaE: 'serena' | 'sonrisa' | 'triste' = f1 ? (s < BUSCO + 0.5 ? 'triste' : 'serena') : s < PERO ? 'triste' : s < JESUS ? 'serena' : 'sonrisa';
  const incE = f1 ? 2 + Math.sin(s * 0.5) * 1.5 : 1 + Math.sin(s * 0.5) * 1.2;
  // telefono
  const flip = rampa(s, BUSCO - 0.3, BUSCO + 0.15);
  const sx = Math.cos(flip * Math.PI);
  const brilloTel = f1 ? rampa(s, TEL, TEL + 0.2) * rampa(s, BUSCO + 0.1, BUSCO + 0.6, 1, 0) : 0;
  // angel (fase 4)
  const aA = f1 ? 0 : rampa(s, E4 + 0.2, E4 + 1.8);
  const aMano = f1 ? 0 : rampa(s, NOTICIA2 - 0.3, NOTICIA2 + 0.9, 0, 1, sal);
  const envBrillo = f1 ? 0 : rampa(s, CONFIAMOS, DUR, 0.15, 1);
  const fl = Math.sin(s * 1.2);
  return (
    <Camara paradas={paradas}>
      <AbsoluteFill>
        <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
          <defs>
            <linearGradient id="kp" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#8a5a44" /><stop offset="0.7" stopColor="#4d312a" /><stop offset="1" stopColor="#2e1d1a" /></linearGradient>
            <linearGradient id="kv" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#ffe9b8" /><stop offset="0.6" stopColor="#ffc98a" /><stop offset="1" stopColor="#f39a6a" /></linearGradient>
            <linearGradient id="kb" x1="0" x2="1" y1="0" y2="1"><stop offset="0" stopColor="#fff4cf" stopOpacity="0.95" /><stop offset="1" stopColor="#ffd08a" stopOpacity="0" /></linearGradient>
            <linearGradient id="km" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#b98a5c" /><stop offset="1" stopColor="#8a6040" /></linearGradient>
            <linearGradient id="kmf" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#6a4430" /><stop offset="1" stopColor="#3a2418" /></linearGradient>
            <linearGradient id="ksob" x1="0" x2="1" y1="0" y2="1"><stop offset="0" stopColor="#fffaf0" /><stop offset="1" stopColor="#e6d8bb" /></linearGradient>
            <linearGradient id="kala" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#ffffff" stopOpacity="0.95" /><stop offset="1" stopColor="#ffe2a0" stopOpacity="0.55" /></linearGradient>
            <linearGradient id="kvest" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#fff6dc" stopOpacity="0.9" /><stop offset="1" stopColor="#ffd890" stopOpacity="0.35" /></linearGradient>
          </defs>
          {/* pared */}
          <rect x={-500} y={-300} width={2080} height={2300} fill="url(#kp)" />
          {/* ventana */}
          <g transform="translate(90 -70)">
          <rect x={64} y={454} width={432} height={572} rx={10} fill="#3a241c" />
          <rect x={84} y={474} width={392} height={532} fill="url(#kv)" />
          <path d="M84 900 L150 860 L210 900 L290 840 L350 890 L420 850 L476 880 L476 1006 L84 1006Z" fill="#c8794f" opacity={0.55} />
          <rect x={272} y={474} width={16} height={532} fill="#3a241c" />
          <rect x={84} y={732} width={392} height={14} fill="#3a241c" />
          {/* cortinas que se mecen */}
          <path d={`M60 440 L${200 + Math.sin(s * 1.1) * 10} 440 Q${150 + Math.sin(s * 1.3) * 22} 760 ${178 + Math.sin(s * 1.2 + 1) * 26} 1040 L60 1040Z`} fill="url(#kvest)" opacity={0.85} />
          <path d={`M500 440 L${380 - Math.sin(s * 1.0) * 10} 440 Q${430 - Math.sin(s * 1.25) * 22} 760 ${404 - Math.sin(s * 1.15 + 2) * 26} 1040 L500 1040Z`} fill="url(#kvest)" opacity={0.85} />
          </g>
          {/* reloj de pared: el tiempo de la espera */}
          <circle cx={940} cy={600} r={62} fill="#f1e4c8" stroke="#3a241c" strokeWidth={8} />
          <line x1={940} y1={600} x2={940} y2={560} stroke="#3a241c" strokeWidth={6} strokeLinecap="round" />
          <line x1={940} y1={600} x2={940 + Math.sin((s * 6 * Math.PI) / 180) * 48} y2={600 - Math.cos((s * 6 * Math.PI) / 180) * 48} stroke="#b0432e" strokeWidth={3} strokeLinecap="round" />
          <circle cx={940} cy={600} r={5} fill="#3a241c" />
          {/* repisa con frascos */}
          <rect x={620} y={820} width={380} height={14} fill="#3a241c" />
          {[650, 720, 800, 880, 950].map((jx, i) => <g key={jx}><rect x={jx - 22} y={760 - (i % 2) * 14} width={44} height={60 + (i % 2) * 14} rx={8} fill={['#c98c4a', '#8a6a46', '#d9b57a', '#7a5a3a', '#c4783a'][i]} opacity={0.9} /><rect x={jx - 16} y={752 - (i % 2) * 14} width={32} height={12} rx={4} fill="#3a241c" /></g>)}
          {/* haz de luz de la ventana */}
          <polygon points={`210,490 540,490 ${1060 + fl * 24},1320 ${420 + fl * 24},1320`} fill="url(#kb)" style={{mixBlendMode: 'screen'}} opacity={0.22 + 0.45 * luz} />
          {/* angel de luz detras de ella: sin rostro, cabeza con aureola, alas suaves y la mano en su hombro */}
          {aA > 0.001 && (
            <g opacity={aA}>
              <path d={`M600 700 Q${440 + fl * 8} 540 ${370 + fl * 10} 470 Q${360 + fl * 8} 760 490 1010Z`} fill="url(#kala)" opacity={0.95} />
              <path d={`M680 700 Q${840 - fl * 8} 540 ${910 - fl * 10} 470 Q${920 - fl * 8} 760 790 1010Z`} fill="url(#kala)" opacity={0.95} />
              <path d={`M606 710 Q${500 + fl * 6} 600 ${450 + fl * 8} 560 Q${450 + fl * 6} 770 520 940Z`} fill="#fffaf0" opacity={0.7} />
              <path d={`M674 710 Q${780 - fl * 6} 600 ${830 - fl * 8} 560 Q${830 - fl * 6} 770 760 940Z`} fill="#fffaf0" opacity={0.7} />
              <path d="M560 700 Q540 900 450 1300 L830 1300 Q740 900 720 700Z" fill="url(#kala)" opacity={0.85} />
              <rect x={618} y={655} width={44} height={60} rx={14} fill="#fff3d8" opacity={0.95} />
              <ellipse cx={640} cy={610} rx={50} ry={60} fill="#fffaf0" opacity={0.96} />
              <ellipse cx={640} cy={536} rx={62} ry={14} fill="none" stroke="#fff3c0" strokeWidth={6} opacity={0.95} />
            </g>
          )}
          {/* esposo e hijo (abrazo) o esposo (fase 4) */}
