          <polygon points={`430,-100 650,-100 ${930 + Math.sin(s * 0.6) * 20},1350 ${150 - Math.sin(s * 0.6) * 20},1350`} fill="url(#cc)" style={{mixBlendMode: 'screen'}} opacity={cono} />
        </svg>
        <Brillo x={540} y={1180} r={420 + 120 * hoja} color={`rgba(255,226,150,${0.3 + 0.35 * hoja})`} />
        <Brillo x={870} y={680} r={420} color="rgba(255,244,210,0.45)" />
        <Polvo n={34} x0={260} x1={820} y0={1320} y1={100} vel={24} sem={11} op={0.95} t0={MEDICOS - 0.4} />
        <Profundidad color="rgba(60,40,20,0.32)" lejos="rgba(255,244,210,0.2)" manchas={2} semilla={6} deriva={0.8} />
      </AbsoluteFill>
    </Camara>
  );
};

